namespace Microsoft.Contoso;

model Widget is ProxyResource<{}> {
  ...ResourceNameParameter<Widget>;
}

@armResourceOperations
interface Widgets {
  delete is ArmResourceDeleteSync<
    Widget,
    Response =
      | (ArmDeletedResponse & {
          @body body: string;
        })
      | ArmDeletedNoContentResponse
  >;
}

